-- 368 fixed historical omissions, corroborated against initializer and original owners.
-- Fixed historical evidence, not a rule deriving owners from departments.
-- Load this file before -check.sql, forward .sql or -rollback.sql in the SAME connection.
SET NAMES utf8mb4;
DROP TEMPORARY TABLE IF EXISTS tmp_task_leader_completion_expected;
CREATE TEMPORARY TABLE tmp_task_leader_completion_expected (
  task_id BIGINT PRIMARY KEY, project_id BIGINT, parent_id BIGINT, root_id BIGINT,
  phase INT, task_code VARCHAR(64) COLLATE utf8mb4_bin,
  old_leader_id BIGINT, wrong_leader_id BIGINT
) ENGINE=InnoDB;
DROP TEMPORARY TABLE IF EXISTS tmp_task_leader_completion_history;
CREATE TEMPORARY TABLE tmp_task_leader_completion_history(task_id BIGINT PRIMARY KEY,leader_after_id BIGINT,rolled_back_at DATETIME);
SET @repair_history_sql=IF(EXISTS(SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE()
  AND TABLE_NAME='sys_task_leader_repair_20261102'),
  'INSERT INTO tmp_task_leader_completion_history SELECT task_id,leader_after_id,rolled_back_at FROM sys_task_leader_repair_20261102','SELECT 1');
PREPARE repair_history_stmt FROM @repair_history_sql;
EXECUTE repair_history_stmt;
DEALLOCATE PREPARE repair_history_stmt;
